    pub(crate) fn map_split_escape(&self, c: char) -> Option<char> {
        let token = c.to_string();
        let mapped = self.catalog_syntax_kind(&token);
        match c {
        'r' => Some('\r'),
        'n' => Some('\n'),
        't' => Some('\t'),
        'f' => Some('\u{000C}'),
        'v' => Some('\u{000B}'),
        '_' => Some(' '),
        '#' => Some('#'),
        '$' => Some('$'),
        '"' => Some('"'),
        _ => {
        let _ = mapped;
        None
        }
        }
    }

    pub(crate) fn is_split_whitespace(&self, c: char) -> bool {
        if matches!(c, ' ' | '\t' | '\r' | '\n' | '\u{000B}' | '\u{000C}') {
        return true;
        }
        if c == '\u{00A0}' {
        return false;
        }
        false
    }

    pub(crate) fn is_split_quote(&self, c: char) -> bool {
        if c == '\'' {
            return true;
