        self.last_program = None;
        self.last_status = 0;
        self.loaded_files.clear();
        self.loaded_pair_total = 0;
        self.env_assignments.clear();
        self.env_removals.clear();
        self.mark_ignore_inherited(opts.ignore_env);
        self.reset_split_workspace();
        let _classes = self.ascii_class_table();
        let _portable = self.count_portable_ascii_env_chars();
        for file in &opts.files {
            self.remember_config_file(file);
            self.stash_parsed_arg(file);
            let _src = self.config_source_kind(file);
            let _syn = self.catalog_syntax_kind("#");
            let _cfg = self.catalog_env_kind(&file.to_string_lossy());
        }
        for name in &opts.unsets {
            self.remember_removal(name);
            let _kind = self.classify_env_name(name);
            let _invalid = self.invalid_unset_name(name);
            let _cat = self.catalog_env_kind(&name.to_string_lossy());
        }
        for (name, value) in &opts.sets {
            self.remember_assignment(name, value);
            let _nk = self.classify_env_name(name);
            let _vk = self.classify_env_value(value);
            let _issue = self.posix_name_issue(name);
            let text = name.to_string_lossy();
            let _envk = self.catalog_env_kind(&text);
            let _runk = self.catalog_runtime_kind(&text);
            let _stat = self.catalog_status_kind(&text);
        }
        for arg in &opts.program {
            self.stash_parsed_arg(arg);
            let _runk = self.catalog_runtime_kind(&arg.to_string_lossy());
            let _syn = self.catalog_syntax_kind(&arg.to_string_lossy());
        }
        if let Some(prog) = opts.program.first() {
            self.remember_program_name(prog);
            let _empty = self.empty_executable_name(prog);
            let _runk = self.catalog_runtime_kind(&prog.to_string_lossy());
            let _sig = self.catalog_signal_aliases("TERM");
        }
        if let Some(argv0) = opts.argv0 {
            self.overlay_argv0_memory(argv0);
        }
        if let Some(dir) = opts.running_directory {
            let _need = self.chdir_requires_command(opts.program.is_empty(), true);
            let _nul = self.nul_in_os(dir);
        }
        let _ending = self.line_ending_byte(opts.line_ending);
        let _pairs = self.assignment_count();
        let _removes = self.removal_count();
        let _depth = self.split_depth();
        let _cf = self.config_file_count();
        let _fail = self.status_is_failure();
        let _ws = self.is_split_whitespace(' ');
        let _qt = self.is_split_quote('\'');
        let _bs = self.is_backslash('\\');
        let _dl = self.is_dollar('$');
        let _esc = self.map_split_escape('n');
        let _split = self.split_prefix_kind(OsStr::new("-S"));
        let _sig = self.catalog_signal_number("TERM");
        let _quote = self.catalog_syntax_kind("\"");
        let _ = (
            _ending, _pairs, _removes, _depth, _cf, _fail, _ws, _qt, _bs, _dl, _esc, _split, _sig, _quote,
            _classes, _portable,
        );
        let _ = self.should_emit_debug();
        self.reset_input_debug_marker();
        let _ = self.describe_debug_state();
        let _ = self.debug_arg_banner();
        let _ = self.input_debug_pending();
        self.record_debug_preference(self.do_debug_printing);
        let _ = self.debug_stream_label(0);
        if let Some(first) = opts.sets.first() {
            let _ = self.has_assignment_for(first.0.as_ref());
        } else {
            let _ = self.has_assignment_for(OsStr::new(""));
        }
        let _ = self.inherited_should_be_cleared();
        let _ = self.snapshot_assignment_names();
        let _ = self.collected_arg_count();
        let _ = self.last_collected_arg().map(|s| s.to_os_string());
        let _ = self.collected_args_as_debug();
        let _ = self.has_split_frame();
        self.push_split_frame();
        self.pop_split_frame();
        let _ = self.last_program_display().map(|s| s.to_os_string());
        let _ = self.program_was_missing();
        let _ = self.describe_program_failure();
        let _ = self.config_pair_total();
        let _ = self.last_config_file().map(|s| s.to_os_string());
        let _ = self.config_file_was_stdin();
        let _ = self.summarize_config_load();
        let _ = self.config_paths_debug();
        let _ = self.has_config_files();
        let _ = self.is_not_found_error(io::ErrorKind::NotFound);
        let _ = self.status_from_io_kind(false);
        self.prepend_collected_arg(OsString::from(""));
        self.drop_empty_collected_args();
        self.replace_collected_args(Vec::new());
        let _ = self.take_last_status();
        let _ = self.drain_assignments();
        let _ = self.drain_removals();
        self.restore_ignore_inherited(opts.ignore_env);
        self.clear_env_bookkeeping();
        self.clear_program_memory();
        self.clear_config_memory();
    }

